cat > app/pages/contact.vue <<'EOF'
<script setup lang="ts">
useHead({ title: 'Contact | Bookshelf' })

interface ContactState {
  values: ContactValues
  errors: ContactErrors
  success: string | null
}

// On a no-JavaScript post, the server middleware has already validated the form.
const event = useRequestEvent()
const state = useState<ContactState>('contact', () => {
  const submission = event?.context.contactSubmission
  return {
    values: { ...(submission?.values ?? { name: '', email: '', message: '' }) },
    errors: { ...(submission?.errors ?? {}) },
    success: submission?.success ?? null,
  }
})

const sending = ref(false)

async function onSubmit() {
  state.value.success = null
  const errors = validateContact(state.value.values)
  state.value.errors = errors
  if (Object.keys(errors).length > 0) return

  sending.value = true
  try {
    const result = await $fetch('/api/contact', {
      method: 'POST',
      body: state.value.values,
      ignoreResponseError: true,
    })
    if (result.ok) {
      state.value.success = result.message
      state.value.values = { name: '', email: '', message: '' }
    }
    else {
      state.value.errors = result.errors
    }
  }
  finally {
    sending.value = false
  }
}

onBeforeUnmount(() => {
  state.value = { values: { name: '', email: '', message: '' }, errors: {}, success: null }
})
</script>

<template>
  <h1>Contact</h1>

  <p v-if="state.success" role="status" class="success">{{ state.success }}</p>

  <form method="post" action="/contact" novalidate class="contact-form" @submit.prevent="onSubmit">
    <div class="field">
      <label for="contact-name">Name</label>
      <input
        id="contact-name"
        v-model="state.values.name"
        type="text"
        name="name"
        autocomplete="name"
        :aria-invalid="state.errors.name ? 'true' : undefined"
        :aria-describedby="state.errors.name ? 'contact-name-error' : undefined"
      >
      <p v-if="state.errors.name" id="contact-name-error" class="error">{{ state.errors.name }}</p>
    </div>

    <div class="field">
      <label for="contact-email">Email</label>
      <input
        id="contact-email"
        v-model="state.values.email"
        type="email"
        name="email"
        autocomplete="email"
        :aria-invalid="state.errors.email ? 'true' : undefined"
        :aria-describedby="state.errors.email ? 'contact-email-error' : undefined"
      >
      <p v-if="state.errors.email" id="contact-email-error" class="error">{{ state.errors.email }}</p>
    </div>

    <div class="field">
      <label for="contact-message">Message</label>
      <textarea
        id="contact-message"
        v-model="state.values.message"
        name="message"
        rows="6"
        :aria-invalid="state.errors.message ? 'true' : undefined"
        :aria-describedby="state.errors.message ? 'contact-message-error' : undefined"
      />
      <p v-if="state.errors.message" id="contact-message-error" class="error">{{ state.errors.message }}</p>
    </div>

    <button type="submit" :disabled="sending">Send</button>
  </form>
</template>
EOF
