// Nuxt answers errors with JSON unless the request looks like it comes from a browser
// (curl, or fetch's `sec-fetch-mode: cors`). Page URLs should always get the HTML 404 page.
export default defineEventHandler((event) => {
  const { pathname } = getRequestURL(event)
  if (/^\/(api|_nuxt|__nuxt)/.test(pathname) || pathname.endsWith('.json')) return

  const accept = event.node.req.headers.accept ?? ''
  if (accept.includes('text/html') || accept.includes('application/json')) return
  event.node.req.headers.accept = accept ? `text/html, ${accept}` : 'text/html'
})
EOF
